-- persons
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-dashi', '耶律大石', ARRAY[]::text[], NULL, NULL, 1087, 1, 1143, 1, ARRAY['皇帝'], '辽太祖后裔，辽亡后率部西行，联结西域势力并于1124年前后建立西辽，号葛儿汗。其政权以巴拉沙衮为中心，控制中亚绿洲与交通要地；在位1124—1143年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律大石"}]'::jsonb, NULL, '德宗', '西辽德宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('xiao-tabuyan', '萧塔不烟', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝','政治家'], '耶律大石遗孀，西辽感天皇后。大石死后她以摄政者身份维持政权，并在其子耶律夷列成年后交还权力；临朝称制1143—1150年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧塔不烟"}]'::jsonb, NULL, NULL, '感天皇后')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-yilie', '耶律夷列', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '耶律大石之子、萧塔不烟之后的西辽君主，承接父辈在中亚建立的统治。其在位期间西辽继续控制七河与河中部分地区；在位1150—1163年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律夷列"}]'::jsonb, NULL, '仁宗', '西辽仁宗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-pusuwan', '耶律普速完', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝','政治家'], '耶律夷列之妹，西辽承天太后，兄长死后以摄政身份掌政。她在宫廷冲突中被处死，耶律直鲁古随后即位；临朝称制1163—1177年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律普速完"}]'::jsonb, NULL, NULL, '承天太后')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-zhilugu', '耶律直鲁古', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '耶律夷列之子、耶律普速完之后继位，统治西辽后期。乃蛮王子屈出律借婚姻与宫廷政变夺权，直鲁古被废，西辽逐渐走向覆亡；在位1177—1211年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律直鲁古"}]'::jsonb, NULL, NULL, '西辽皇帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('qu-chulu', '屈出律', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '乃蛮王子，娶耶律直鲁古之女后夺取西辽权位。其统治引发当地穆斯林反抗，蒙古军西征时攻入西辽，屈出律于1218年被俘处死，政权灭亡；在位1211—1218年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/屈出律"}]'::jsonb, NULL, NULL, '西辽皇帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-chun', '耶律淳', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '辽朝宗室，金军南下时在燕京被拥立为帝，建立短暂的北辽政权，与天祚帝所代表的辽廷并存。其去世后北辽迅速失去凝聚力，燕京亦于1122年被金军攻取；在位1122年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律淳"}]'::jsonb, NULL, NULL, '北辽皇帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('xiao-defei', '萧德妃', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['后妃','政治家'], '耶律淳妃，耶律淳死后临朝称制，北辽旋亡；金军攻取燕京后她与耶律大石离开，后来归附天祚帝并被杀，北辽后续划分有争议。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧德妃"}]'::jsonb, NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-liuge', '耶律留哥', ARRAY[]::text[], NULL, NULL, 1165, 1, 1220, 1, ARRAY['君主'], '金末契丹将领，1213年称辽王、国号辽，改元天统；拒称帝，蒙古仍封辽王。史称东辽。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律留哥"}]'::jsonb, NULL, NULL, '辽王')
