INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yao-li-shi', '姚里氏', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['王后','政治家'], '耶律留哥妻，元史立为妃；留哥卒后佩虎符权领其众七年，请以嫡子薛阇袭爵。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/姚里氏"}]'::jsonb, NULL, NULL, '王后')
