INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-xieshe', '耶律薛阇', ARRAY[]::text[], NULL, NULL, 1193, 1, 1238, 1, ARRAY['君主'], '耶律留哥嫡长子，1226年袭辽王爵，后行广宁路都元帅府事。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律薛阇"}]'::jsonb, NULL, NULL, '辽王')
