INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-shouguonu', '耶律收国奴', ARRAY[]::text[], NULL, NULL, 1215, 1, 1259, 1, ARRAY['君主'], '耶律薛阇之子，1238年袭爵，行广宁府路总管军民万户府事，易名石剌。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律收国奴"}]'::jsonb, NULL, NULL, '辽王')
