INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-gunai', '耶律古乃', ARRAY[]::text[], NULL, NULL, 1234, 1, 1269, 1, ARRAY['君主'], '耶律收国奴长子，1259年嗣爵；至元六年广宁并入东京，去职同年卒。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律古乃"}]'::jsonb, NULL, NULL, '辽王')
