INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yelu-sibu', '耶律厮不', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['宗室'], '留哥属下郡王，1216年僭帝号于澄州，国号辽、改元天威，史称后辽；月余被杀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律厮不"}]'::jsonb, NULL, NULL, NULL)
