VALUES ('dongliao', '东辽', ARRAY['辽'], 'cn', 'east_asia', 1213, 1, 1269, 12, 14556, 15239, 'year', 'ochre', NULL, NULL, '1213年耶律留哥称辽王；1269年耶律古乃去职，广宁并入东京。')
